package cli

import (
	"fmt"
	"os"

	"github.com/mvanhorn/printing-press-library/library/productivity/granola/internal/store"
	"github.com/spf13/cobra"
)

// PATCH(granola-db-schema-discoverability) — agents query the local store
// with sqlite3 directly for questions the commands don't cover, and without
// a published schema they guess column names and fail (`source` for
// `row_source`, `name` for folders' `title`). `db schema` prints the store
// path and the real tables/columns so a script can read the contract
// instead of probing PRAGMA by trial and error.
func newDBCmd(flags *rootFlags) *cobra.Command {
	cmd := &cobra.Command{
		Use:   "db",
		Short: "Inspect the local SQLite store",
	}
	cmd.AddCommand(newDBSchemaCmd(flags))
	return cmd
}

type dbColumn struct {
	Name    string `json:"name"`
	Type    string `json:"type"`
	NotNull bool   `json:"not_null"`
	PK      bool   `json:"pk"`
}

type dbTable struct {
	Name    string     `json:"name"`
	Columns []dbColumn `json:"columns"`
}

type dbSchemaOutput struct {
	Path   string    `json:"path"`
	Tables []dbTable `json:"tables"`
}

func newDBSchemaCmd(flags *rootFlags) *cobra.Command {
	var dbPath string
	cmd := &cobra.Command{
		Use:   "schema",
		Short: "Print the local store's path, tables, and columns",
		Example: `  # Every table and column, human-readable
  granola-pp-cli db schema

  # Machine-readable, for scripts that query the store directly
  granola-pp-cli db schema --json

  # Just one table's columns
  granola-pp-cli db schema --json --select tables.name,tables.columns`,
		Annotations: map[string]string{
			"mcp:read-only": "true",
		},
		RunE: func(cmd *cobra.Command, args []string) error {
			if dryRunOK(flags) {
				return nil
			}
			if dbPath == "" {
				dbPath = defaultDBPath("granola-pp-cli")
			}
			if _, err := os.Stat(dbPath); os.IsNotExist(err) {
				return notFoundErr(fmt.Errorf("no local store at %s — run sync first", dbPath))
			}
			// Read-only by contract: inspection must not run migrations,
			// EnsureSchema, or leave WAL/SHM files behind — least of all on
			// an arbitrary --db file that may not even be a granola store.
			// The snapshot open creates no side files at all; the schema
			// printed is whatever the file actually contains.
			s, err := store.OpenSnapshot(dbPath)
			if err != nil {
				return err
			}
			defer s.Close()

			rows, err := s.DB().QueryContext(cmd.Context(),
				`SELECT name FROM sqlite_master WHERE type = 'table' AND name NOT LIKE 'sqlite_%' ORDER BY name`)
			if err != nil {
				return err
			}
			defer rows.Close()
			var names []string
			for rows.Next() {
				var n string
				if err := rows.Scan(&n); err != nil {
					return err
				}
				names = append(names, n)
			}
			if err := rows.Err(); err != nil {
				return err
			}

			out := dbSchemaOutput{Path: dbPath}
			for _, n := range names {
				cols, err := tableColumns(cmd, s, n)
				if err != nil {
					return err
				}
				out.Tables = append(out.Tables, dbTable{Name: n, Columns: cols})
			}

			if flags.asJSON || !isTerminal(cmd.OutOrStdout()) {
				return emitJSON(cmd, flags, out)
			}
			w := cmd.OutOrStdout()
			fmt.Fprintf(w, "Store: %s\n", out.Path)
			for _, t := range out.Tables {
				fmt.Fprintf(w, "\n%s\n", t.Name)
				for _, c := range t.Columns {
					suffix := ""
					if c.PK {
						suffix = "  (pk)"
					}
					fmt.Fprintf(w, "  %-24s %s%s\n", c.Name, c.Type, suffix)
				}
			}
			return nil
		},
	}
	cmd.Flags().StringVar(&dbPath, "db", "", "Database path (default: ~/.local/share/granola-pp-cli/data.db)")
	return cmd
}

// tableColumns reads PRAGMA table_info for one table. The table name comes
// from sqlite_master, not user input, so string interpolation is safe here;
// PRAGMA does not accept bound parameters.
func tableColumns(cmd *cobra.Command, s *store.Store, table string) ([]dbColumn, error) {
	rows, err := s.DB().QueryContext(cmd.Context(), fmt.Sprintf(`PRAGMA table_info(%q)`, table))
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var cols []dbColumn
	for rows.Next() {
		var cid int
		var name, ctype string
		var notnull, pk int
		var dflt any
		if err := rows.Scan(&cid, &name, &ctype, &notnull, &dflt, &pk); err != nil {
			return nil, err
		}
		cols = append(cols, dbColumn{Name: name, Type: ctype, NotNull: notnull != 0, PK: pk != 0})
	}
	return cols, rows.Err()
}
